  test-db-1:
    image: postgres:16
    environment:
      POSTGRES_DB: testdb_1
  test-db-2:
    image: postgres:16
    environment:
      POSTGRES_DB: testdb_2
  # ... до 8 БД для 8 параллельных процессов
```

